import java.io.*;import java.util.*;import com.reandroid.apk.*;import com.reandroid.arsc.chunk.*;import com.reandroid.arsc.chunk.xml.*;import com.reandroid.arsc.model.*;import com.reandroid.arsc.value.*;import org.xmlpull.v1.*;
public class XLayoutAudit{
public static void main(String[] a)throws Exception{try(ApkModule apk=ApkModule.loadApkFile(new File(a[0]))){apk.setLoadDefaultFramework(false);TableBlock t=apk.getTableBlock();for(String name:new String[]{"main_activity_bottom_nav_view_pager","home_title","home_timeline_list_content_description"}){String type=name.startsWith("main_")?"layout":"string";ResourceEntry r=t.getResource("com.twitter.android",type,name);System.out.println(r);if(r==null)continue;for(Entry e:r){if(type.equals("string")){if(e.getTypeBlock().getResConfig().toString().contains("ja")||e.getTypeBlock().getResConfig().toString().equals(""))System.out.println(e.getTypeBlock().getResConfig()+" "+e.getValueAsString());}else{String path=e.getValueAsString();ResXmlDocument doc=apk.getResFile(path).readAsXmlDocument();doc.setPackageBlock(t.pickOne());XmlSerializer s=XmlPullParserFactory.newInstance().newSerializer();s.setOutput(new OutputStreamWriter(System.out));doc.serialize(s);s.flush();}}}}}
}
